-- Streamazon: im Supabase SQL Editor EINMAL komplett ausführen.
create table admins(user_id uuid primary key references auth.users on delete cascade);
create function is_admin() returns boolean language sql security definer stable set search_path=public as $$ select exists(select 1 from public.admins where user_id=auth.uid()) $$;

create table categories(pos bigserial, id text primary key, name text not null, kind text not null default 'p' check (kind in ('p','s')));
create table products(pos bigserial, id text primary key, cat text, name text not null, tex text default '', price int check (price is null or price>=0), descr text default '',
 variants jsonb not null default '[]', attrs jsonb not null default '[]', featured bool default false, sale int check (sale is null or sale>=0),
 struck bool default false, active bool default true, demo bool default false, type text);
create table enchantments(pos bigserial, id text primary key, name text not null, price int not null default 0 check (price>=0), types text[] not null default '{}');
create table delivery_options(pos bigserial, key text primary key, label text not null, price int not null default 0 check (price>=0), descr text default '');
create sequence order_no start 1001;
create table orders(no int primary key default nextval('order_no'), name text not null, status text not null default 'queue' check (status in ('queue','work','ready','done')),
 delivery text, fee int default 0, total int, items jsonb not null default '[]', created_at timestamptz default now());

alter table admins enable row level security; alter table categories enable row level security; alter table products enable row level security;
alter table enchantments enable row level security; alter table delivery_options enable row level security; alter table orders enable row level security;

create policy "admin sieht sich" on admins for select using (user_id=auth.uid());
create policy "kategorien lesen" on categories for select using (true);
create policy "verzauberungen lesen" on enchantments for select using (true);
create policy "lieferoptionen lesen" on delivery_options for select using (true);
create policy "produkte lesen" on products for select using (active or is_admin());
create policy "kategorien admin" on categories for all using (is_admin()) with check (is_admin());
create policy "verzauberungen admin" on enchantments for all using (is_admin()) with check (is_admin());
create policy "lieferoptionen admin" on delivery_options for all using (is_admin()) with check (is_admin());
create policy "produkte admin" on products for all using (is_admin()) with check (is_admin());
create policy "bestellungen admin" on orders for all using (is_admin()) with check (is_admin());
-- Bestellungen sind für normale Besucher NICHT direkt lesbar (enthalten Ingame-Namen).

-- Öffentliche Ansicht für den Tab "Bestellungen": ohne Namen, ohne private Notizen.
create view public_orders as
 select no, status, delivery, created_at,
  (select coalesce(jsonb_agg(i - 'note' - 'dims'), '[]'::jsonb) from jsonb_array_elements(items) i) as items
 from orders;
grant select on public_orders to anon, authenticated;

-- Bestellung aufgeben (ohne Konto). Fortschritt startet immer bei 0, Eingaben werden begrenzt.
create function place_order(p_name text, p_delivery text, p_fee int, p_total int, p_items jsonb) returns int
language plpgsql security definer set search_path=public as $$
declare n int; clean jsonb;
begin
 if p_name is null or length(trim(p_name))=0 or length(p_name)>40 then raise exception 'Ingame-Name fehlt'; end if;
 if jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items) not between 1 and 50 then raise exception 'Ungültige Bestellung'; end if;
 select jsonb_agg(jsonb_build_object('name',left(i->>'name',120),'variant',i->>'variant','qty',greatest(1,least(9999,(i->>'qty')::int)),'done',0,
   'unit',i->>'unit','piece',coalesce((i->>'piece')::bool,false),'note',left(i->>'note',2000),'dims',left(i->>'dims',200))) into clean
  from jsonb_array_elements(p_items) i;
 insert into orders(name,delivery,fee,total,items) values(trim(p_name),p_delivery,greatest(0,coalesce(p_fee,0)),p_total,clean) returning no into n;
 return n;
end $$;
grant execute on function place_order(text,text,int,int,jsonb) to anon, authenticated;

-- Bilder (Produktbilder, öffentlich lesbar, nur Admins dürfen hochladen)
insert into storage.buckets(id,name,public) values('media','media',true) on conflict do nothing;
create policy "media lesen" on storage.objects for select using (bucket_id='media');
create policy "media admin" on storage.objects for all using (bucket_id='media' and is_admin()) with check (bucket_id='media' and is_admin());

-- Live-Updates im Shop
alter publication supabase_realtime add table products, categories, enchantments, delivery_options;

